import * as React from "react";
import { useState } from "react";
import MappingForm from "./MappingForm";
import ActivateMeetingForm from "./ActivateMeetingForm";
import { MappingRule, initMsal } from "../services/graph";
import "./App.css";

type Tab = "submit" | "mapping";

// Initialize MSAL once (no-op if msal CDN not loaded)
initMsal();

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>("submit");
  // Shared rules state — MappingForm loads & writes, ActivateMeetingForm reads
  const [rules, setRules] = useState<MappingRule[]>([]);

  return (
    <div className="app-root">
      {/* ── Header ── */}
      <header className="app-header">
        <div className="header-left">
          <div className="logo-dot" />
          <span className="header-title">Conectado</span>
        </div>
      </header>

      {/* ── Tab Bar ── */}
      <nav className="tab-bar">
        <button
          className={`tab${activeTab === "submit" ? " active" : ""}`}
          onClick={() => setActiveTab("submit")}
        >
          Activate Meeting
        </button>
        <button
          className={`tab${activeTab === "mapping" ? " active" : ""}`}
          onClick={() => setActiveTab("mapping")}
        >
          Mapping Editor
        </button>
      </nav>

      {/* ── Tab Content ── */}
      <div className="tab-content-area">
        {activeTab === "submit" ? (
          <ActivateMeetingForm rules={rules} />
        ) : (
          <MappingForm rules={rules} onRulesChange={setRules} />
        )}
      </div>
    </div>
  );
};

export default App;
