import * as React from "react";
import { useState } from "react";
import { MappingRule } from "../services/graph";
import { activateMeeting } from "../services/api";

interface ActivateMeetingFormProps {
    rules: MappingRule[];
}

type AlertType = "error" | "success" | "warning";

interface AlertState {
    msg: string;
    type: AlertType;
}

const ActivateMeetingForm: React.FC<ActivateMeetingFormProps> = ({ rules }) => {
    const today = new Date().toISOString().split("T")[0];
    const [subject, setSubject] = useState("");
    const [date, setDate] = useState(today);
    const [loading, setLoading] = useState(false);
    const [alert, setAlert] = useState<AlertState | null>(null);

    const showAlert = (msg: string, type: AlertType = "error") => setAlert({ msg, type });
    const clearAlert = () => setAlert(null);

    // Find matching rule (case-insensitive)
    const matched = rules.find((r) => r.meeting_subject.toLowerCase() === subject.trim().toLowerCase());

    const handleSubmit = async () => {
        if (!subject.trim() || !date) {
            showAlert("Please enter both meeting subject and date.");
            return;
        }

        if (!matched) {
            showAlert(
                "No mapping found for this subject. Add one in the Mapping Editor tab.",
                "warning"
            );
            return;
        }

        clearAlert();
        setLoading(true);

        try {
            await activateMeeting({
                meetingName: subject.trim(),
                meetingDate: date,
                meetingProject: matched.project_name,
                sampleTask: matched.sample_task,
            });
            showAlert("✓ Meeting activated successfully!", "success");
            setSubject("");
            setDate(today);
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            showAlert(`Activation failed: ${msg}`);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="tab-panel">
            <div className="card">
                <div className="form-group">
                    <label htmlFor="meeting-subject">Meeting Subject</label>
                    <input
                        id="meeting-subject"
                        type="text"
                        placeholder="e.g. Scrum Call"
                        value={subject}
                        onChange={(e) => {
                            setSubject(e.target.value);
                            clearAlert();
                        }}
                    />
                </div>
                <div className="form-group">
                    <label htmlFor="meeting-date">Meeting Date</label>
                    <input
                        id="meeting-date"
                        type="date"
                        value={date}
                        onChange={(e) => setDate(e.target.value)}
                    />
                </div>

                {/* Mapping preview */}
                {subject.trim() && matched && (
                    <div className="mapping-preview">
                        <div className="preview-row">
                            <span className="preview-label">Project</span>
                            <span className="preview-value">{matched.project_name}</span>
                        </div>
                        <div className="preview-row">
                            <span className="preview-label">Task</span>
                            <span className="preview-value">{matched.sample_task}</span>
                        </div>
                    </div>
                )}
                {subject.trim() && !matched && (
                    <div className="alert alert-warning" style={{ marginBottom: "10px" }}>
                        No mapping found for this subject. Add one in the Mapping Editor tab.
                    </div>
                )}

                <button
                    className="btn btn-primary btn-full"
                    disabled={loading}
                    onClick={handleSubmit}
                >
                    {loading ? <span className="btn-spinner" /> : "Activate Meeting"}
                </button>

                {alert && <div className={`alert alert-${alert.type}`}>{alert.msg}</div>}
            </div>
        </div>
    );
};

export default ActivateMeetingForm;
