/* eslint-disable @typescript-eslint/no-explicit-any */
import { CONFIG } from "./config";

// MSAL is loaded from CDN — declare it as `any` to avoid needing @types/msal
declare const msal: any;

// ─── Types ───────────────────────────────────────────────────────────────────
export interface MappingRule {
    id: string;
    meeting_subject: string;
    project_name: string;
    sample_task: string;
}

// ─── MSAL setup ──────────────────────────────────────────────────────────────
let msalApp: any = null;
let graphToken: string | null = null;

const GRAPH_BASE = "https://graph.microsoft.com/v1.0";

export function initMsal(): void {
    // @ts-ignore – msal is loaded from CDN
    if (typeof msal === "undefined") return;
    // @ts-ignore
    msalApp = new msal.PublicClientApplication({
        auth: {
            clientId: CONFIG.MSAL_CLIENT_ID,
            authority: `https://login.microsoftonline.com/${CONFIG.MSAL_TENANT_ID}`,
            redirectUri: window.location.origin + window.location.pathname,
        },
        cache: { cacheLocation: "localStorage", storeAuthStateInCookie: false },
    });
}

async function acquireGraphToken(): Promise<string | null> {
    if (!msalApp) return null;
    const scopes = ["Files.ReadWrite.AppFolder", "openid", "profile"];
    // @ts-ignore
    const accounts = msalApp.getAllAccounts();
    const request = { scopes, account: accounts[0] || undefined };
    try {
        // @ts-ignore
        const resp = await msalApp.acquireTokenSilent(request);
        return resp.accessToken;
    } catch {
        try {
            // @ts-ignore
            const resp = await msalApp.acquireTokenPopup({ scopes });
            return resp.accessToken;
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            console.warn("Could not obtain MS Graph token:", msg);
            return null;
        }
    }
}

// ─── OneDrive helpers (App Folder) ───────────────────────────────────────────
// Files are stored in: OneDrive › Apps › <your-app-name>
// Path: /me/drive/special/approot

export async function loadMappingFromOneDrive(): Promise<MappingRule[]> {
    graphToken = await acquireGraphToken();
    if (!graphToken) return []; // graceful fallback – no OneDrive access
    try {
        const url = `${GRAPH_BASE}/me/drive/special/approot:/${CONFIG.ONEDRIVE_FILE_PATH}:/content`;
        const resp = await fetch(url, {
            headers: { Authorization: `Bearer ${graphToken}` },
        });
        if (resp.status === 404) return [];
        if (!resp.ok) throw new Error(`Load mapping: ${resp.status}`);
        return await resp.json();
    } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        console.warn("loadMappingFromOneDrive:", msg);
        return [];
    }
}

export async function saveMappingToOneDrive(rules: MappingRule[]): Promise<void> {
    if (!graphToken) {
        graphToken = await acquireGraphToken();
        if (!graphToken) throw new Error("No Microsoft Graph token — cannot save to OneDrive");
    }
    const url = `${GRAPH_BASE}/me/drive/special/approot:/${CONFIG.ONEDRIVE_FILE_PATH}:/content`;
    const resp = await fetch(url, {
        method: "PUT",
        headers: {
            Authorization: `Bearer ${graphToken}`,
            "Content-Type": "application/json",
        },
        body: JSON.stringify(rules, null, 2),
    });
    if (!resp.ok) {
        const err = await resp.text();
        throw new Error(`Save mapping: ${resp.status} — ${err}`);
    }
}
